import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/opt/tools'); import casa_tool
s=casa_tool.Session();m=s.model;d0=s.data;sid=m.site('gripper0_right_grip_site').id;qids=np.array([m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)]);dofs=np.array([m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)]);jids=[m.joint(f'robot0_joint{i}').id for i in range(1,8)];cup=d0.xpos[m.body('brewed_coffee_main').id].copy();Rg=np.array([[0,1,0],[0,0,-1],[-1,0,0]])
for dy in [.03,.04,.05]:
 target=cup+np.array([0,dy,.05]);d=mujoco.MjData(m);d.qpos[:]=d0.qpos
 for it in range(400):
  mujoco.mj_forward(m,d);ep=target-d.site_xpos[sid];er=Rotation.from_matrix(Rg@d.site_xmat[sid].reshape(3,3).T).as_rotvec()
  if np.linalg.norm(ep)<.004 and np.linalg.norm(er)<.025:break
  jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,d,jp,jr,sid);J=np.vstack([jp[:,dofs],.35*jr[:,dofs]]);dq=J.T@np.linalg.solve(J@J.T+.03**2*np.eye(6),np.r_[ep,.35*er]);dq=np.clip(dq,-.08,.08)
  for j,jid in enumerate(jids):lo,hi=m.jnt_range[jid];d.qpos[qids[j]]=np.clip(d.qpos[qids[j]]+dq[j],lo+.01,hi-.01)
 mujoco.mj_forward(m,d); pairs=set();
 for c in range(d.ncon):
  co=d.contact[c];a=m.geom(co.geom1).name;b=m.geom(co.geom2).name
  if 'gripper0' in a+b and ('coffee_machine' in a+b or 'brewed_coffee' in a+b):
   if 'brewed_coffee' in a+b: pairs.add((a.split('_')[-1],b.split('_')[-1]))
   else: pairs.add(('machine',a if 'coffee_machine' in a else b))
 print('dy',dy,'err',round(np.linalg.norm(target-d.site_xpos[sid]),3),'contacts',pairs)
